<template><view class="page"><view class="page-return" @click="backHome">‹ 返回首页</view><view class="card"><view class="tabs"><text :class="{active:type==='EXPENSE'}" @click="selectType('EXPENSE')">支出</text><text :class="{active:type==='INCOME'}" @click="selectType('INCOME')">收入</text></view><view class="field"><text>金额</text><input v-model="amount" type="digit" placeholder="0.00" /></view><view class="field"><text>{{ type==='EXPENSE'?'支出':'收入' }}分类</text><picker :range="categories" :value="category" @change="category=$event.detail.value"><view>{{ categories[category] }}</view></picker></view><view class="field"><text>资金计划</text><picker :range="planNames" :value="planIndex" @change="planIndex=$event.detail.value"><view>{{ planNames[planIndex] || '不归入计划' }}</view></picker></view><view class="field"><text>备注</text><input v-model="note" placeholder="可选，例如朋友生日礼物" /></view><view class="field"><text>日期</text><picker mode="date" :value="occurredOn" @change="occurredOn=$event.detail.value"><view>{{ occurredOn }}</view></picker></view><view class="primary" @click="save">{{ editingId ? '保存修改' : '保存账单' }}</view><view v-if="editingId" class="delete-button" @click="remove">删除这笔账单</view></view><WalletMascot /></view></template>
<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { api } from '../../utils/api'
import WalletMascot from '../../components/WalletMascot.vue'
const today = new Date().toISOString().slice(0,10)
const type=ref('EXPENSE'), amount=ref(''), note=ref(''), category=ref(0), planIndex=ref(0), plans=ref([]), occurredOn=ref(today), editingId=ref(null)
const expense=['餐饮·正餐','零食饮品','居家买菜','交通出行','房租房贷','水电燃气','通讯网络','日用清洁','娱乐休闲','服饰美容','运动健康','人情礼物','家庭孝敬','宠物','学习成长','医疗健康','旅行度假','理财保险','税费','公益捐赠','其他']
const income=['生活费','工资薪酬','奖金补贴','报销到账','兼职副业','投资收益','礼金红包','退款返现','其他收入']
const categories=computed(()=>type.value==='EXPENSE'?expense:income); const planNames=computed(()=>['不归入计划',...plans.value.map(item=>item.name)])
function selectType(next){ if(type.value !== next){ type.value=next; category.value=0 } }
onLoad(async options=>{ try { plans.value=await api('/plans'); if(options.id) await loadRecord(options.id) } catch(error) { uni.showToast({title:error?.message || '页面加载失败',icon:'none'}) } })
async function loadRecord(id){ const rows=await api('/transactions'); const row=rows.find(item=>String(item.id)===String(id)); if(!row)return uni.showToast({title:'账单不存在',icon:'none'}); editingId.value=row.id; type.value=row.type; amount.value=String(row.amount); note.value=row.note || ''; occurredOn.value=row.occurredOn; category.value=categories.value.indexOf(row.category); if(category.value<0)category.value=0; planIndex.value=row.planId ? Math.max(0,plans.value.findIndex(plan=>plan.id===row.planId)+1) : 0 }
function payload(){return {type:type.value,category:categories.value[category.value],amount:Number(amount.value),planId:planIndex.value?plans.value[planIndex.value-1].id:null,note:note.value,occurredOn:occurredOn.value}}
async function save(){ if(!Number(amount.value)) return uni.showToast({title:'请输入金额',icon:'none'}); try { await api(editingId.value?`/transactions/${editingId.value}`:'/transactions',{method:editingId.value?'PUT':'POST',data:payload()}); uni.showToast({title:editingId.value?'已修改':'已保存'}); setTimeout(()=>editingId.value?uni.navigateBack():uni.switchTab({url:'/pages/bills/index'}),450) } catch(error) { uni.showToast({title:error?.message || '保存失败',icon:'none'}) } }
function remove(){uni.showModal({title:'删除这笔账单？',content:'删除后会释放对应计划额度，且无法恢复。',confirmColor:'#b56f55',success:async result=>{if(!result.confirm)return;try{await api(`/transactions/${editingId.value}`,{method:'DELETE'});uni.showToast({title:'已删除'});setTimeout(()=>uni.navigateBack(),350)}catch(error){uni.showToast({title:error?.message || '删除失败',icon:'none'})}}})}
function backHome(){ uni.reLaunch({url:'/pages/index/index'}) }
</script><style scoped>.page-return{display:inline-block;color:#58744e;background:#eef8ea;border:1rpx solid #dcebd6;border-radius:999rpx;font-size:24rpx;padding:10rpx 18rpx;margin:0 0 18rpx}.tabs{display:flex;gap:18rpx;margin-bottom:30rpx}.tabs text{padding:12rpx 26rpx;background:#eef3eb;border-radius:999rpx;color:#6c8066}.tabs .active{background:#CEEBC5;color:#58744e;font-weight:700}.field{padding:22rpx 0;border-bottom:1rpx solid #edf2ea;display:flex;justify-content:space-between;gap:30rpx}.field text{color:#6c8066}.field input,.field picker{flex:1;text-align:right}.delete-button{text-align:center;color:#b56f55;font-size:25rpx;padding:25rpx 0 4rpx}</style>
